INSERT INTO "vestigingen" ("id","name","address","city","postal_code","description","description_en","archived_at","created_at","updated_at","image_url") VALUES('ce3bd461f11895258095c5494c23b588','Naamsestraat 29A','Naamsestraat 29A','Leuven','3000',replace('Dit gebouw biedt unieke studentenkamers in het hart van Leuven. Je woont hier op een toplocatie, op wandelafstand van de universiteit, winkels en het bruisende stadsleven.\n\nHet gebouw beschikt over een gezellige centrale buitenruimte met vijf aparte ingangen die elk toegang geven tot verschillende kamers. Daarnaast is er een recent vernieuwde gemeenschappelijke keuken met televisie, ideaal om samen te koken en te ontspannen.\n\nEr is bovendien een veilige en afgesloten fietsenstalling voorzien.\n\nComfort in elke kamer\n\nAlle kamers zijn uitgerust met:\n\nDubbele beglazing\n\nKotnet (internetverbinding)\n\nParlofoon\n\nAansluitmogelijkheid voor kabeltelevisie\n\nWarm en koud water\n\nDe douches en toiletten zijn gemeenschappelijk en worden netjes onderhouden.','\n',char(10)),replace('Located in the heart of Leuven, Naamsestraat 29A offers unique student rooms in a prime location — within walking distance of the university, shops, and the vibrant city centre.\n\nThe building features a cosy central outdoor area with five separate entrances, each leading to different rooms. There is also a recently renovated communal kitchen with television, ideal for cooking together and relaxing.\n\nA secure, enclosed bicycle storage is also available.\n\nComfort in every room\n\nAll rooms are equipped with:\n\nDouble glazing\n\nKotnet (internet connection)\n\nVideo intercom\n\nCable television connection\n\nHot and cold water\n\nThe shared showers and toilets are communally maintained and kept clean.','\n',char(10)),NULL,'2026-02-23 09:55:31','2026-03-23 11:49:50','https://pub-1dc25e3e45174c0e913fc701f51ab106.r2.dev/uploads/3f48eef3-34e8-4256-9b35-29e2fd33aa77-Naamsestraat_29A.png');
INSERT INTO "vestigingen" ("id","name","address","city","postal_code","description","description_en","archived_at","created_at","updated_at","image_url") VALUES('d51d0e166e3387f845dd7ae64b1490c5','J.P. Minckelersstraat 79','J.P. Minckelersstraat 79','Leuven','3000',replace('Gelegen op een ideale locatie vlak bij het centrum van Leuven, biedt J.P. Minckelersstraat 79 een gevarieerd aanbod aan studentenkamers voor elke woonwens en elk budget.\n\nJe kan kiezen uit twee types:\n\nStandaard studentenkamer met gedeeld sanitair — betaalbaar en gezellig\n\nStudio met privébadkamer — meer privacy en comfort\n\nDe residentie combineert een centrale ligging met een rustige woonomgeving, op wandelafstand van de universiteit, winkels en openbaar vervoer.\n\nSfeer & voorzieningen\n\nVeilige en afgesloten fietsenstalling\n\nGemeenschappelijke ruimtes netjes onderhouden\n\nVlakbij openbaar vervoer','\n',char(10)),replace('Ideally located close to the centre of Leuven, J.P. Minckelersstraat 79 offers a varied range of student rooms to suit every lifestyle and budget.\n\nYou can choose from two types:\n\nStandard student room with shared bathroom — affordable and sociable\n\nStudio with private bathroom — more privacy and comfort\n\nThe residence combines a central location with a quiet living environment, within walking distance of the university, shops, and public transport.\n\nFacilities & amenities\n\nSecure, enclosed bicycle storage\n\nCommunal areas kept clean and well-maintained\n\nClose to public transport','\n',char(10)),NULL,'2026-02-23 10:00:25','2026-03-23 11:49:50','https://pub-1dc25e3e45174c0e913fc701f51ab106.r2.dev/uploads/443ddadf-3778-482b-9092-c72a622e472f-J.P._Minckelersstraat_79.png');
INSERT INTO "vestigingen" ("id","name","address","city","postal_code","description","description_en","archived_at","created_at","updated_at","image_url") VALUES('637f58e754b17199ea92ac04c79e74da','Dreefstraat 104','Dreefstraat 104',' Heverlee','3001',replace('Dreefstraat 104 in Heverlee biedt nieuwe, moderne en volledig gemeubelde studentenkamers — klaar om in te trekken. De residentie is rustig gelegen, vlakbij de campus en op een vlotte afstand van het bruisende centrum van Leuven.\n\nBeschikbare oppervlaktes\n\n12 m²\n\n14 m²\n\n17 m²\n\n18 m²\n\n21 m²\n\n35 m²\n\nZo vind je altijd een kamer die perfect aansluit bij jouw wensen en budget.\n\nGemeenschappelijke voorzieningen\n\nRuime gemeenschappelijke keuken volledig uitgerust\n\nGezellige living met televisie\n\nVeilige fietsenstalling\n\nAlle kamers zijn modern ingericht en instapklaar.','\n',char(10)),replace('Dreefstraat 104 in Heverlee offers new, modern, and fully furnished student rooms — ready to move in. The residence is quietly situated, close to the campus and within easy reach of the lively centre of Leuven.\n\nAvailable sizes\n\n12 m²\n\n14 m²\n\n17 m²\n\n18 m²\n\n21 m²\n\n35 m²\n\nThere is always a room that perfectly matches your needs and budget.\n\nCommunal facilities\n\nFully equipped communal kitchen\n\nCosy living room with television\n\nSecure bicycle storage\n\nAll rooms are modern and move-in ready.','\n',char(10)),NULL,'2026-02-23 10:05:34','2026-03-23 11:49:50','https://pub-1dc25e3e45174c0e913fc701f51ab106.r2.dev/uploads/dcb5fa54-0c32-41eb-bff9-3945cb6bad09-D106_gevel.JPG');
INSERT INTO "vestigingen" ("id","name","address","city","postal_code","description","description_en","archived_at","created_at","updated_at","image_url") VALUES('04cb31a0552a92bec75648fe4f2a2e32','J.P. Minckelersstraat 104 – 106','J.P. Minckelersstraat 104 – 106','Leuven','3000',replace('J.P. Minckelersstraat 104–106 is één van de meest complete studentenresidenties van Mijn-Kot. Het gebouw biedt een breed gamma aan kamerformats, van compacte kamers tot ruime studio''s en duplexen — allemaal modern ingericht en volledig gemeubeld.\n\nDuplexkamers met privé-sanitair\n\nRuime, lichte duplexkamers in oppervlaktes van 14 m², 16 m², 17 m², 20 m², 21 m², 25 m² en 30 m². Ideaal voor wie privacy en comfort combineert met gedeelde voorzieningen.\n\nDubbele kamers\n\nVolledig van elkaar gescheiden, elk met eigen sanitair. Geschikt voor twee personen of voor wie extra ruimte wenst.\n\nRuime kamers & studio''s\n\nOppervlaktes van 21 m² tot 40 m², met toegang tot een gemeenschappelijke tuin — perfect om te ontspannen tussen de studiesessies door.\n\nGemeenschappelijke voorzieningen\n\nGemeenschappelijke keuken en gezellige living met televisie\n\nAangelegde tuin voor alle bewoners\n\nVeilige fietsenstalling','\n',char(10)),replace('J.P. Minckelersstraat 104–106 is one of the most complete student residences in the Mijn-Kot portfolio. The building offers a wide range of room formats — from compact rooms to spacious studios and duplexes — all modern and fully furnished.\n\nDuplex rooms with private bathroom\n\nBright and spacious duplexes available in 14 m², 16 m², 17 m², 20 m², 21 m², 25 m² and 30 m². Perfect for those who value privacy and comfort alongside shared facilities.\n\nDouble rooms\n\nFully separated from each other, each with private bathroom. Suitable for two people or for those who want extra space.\n\nSpacious rooms & studios\n\nSizes from 21 m² to 40 m², with access to a communal garden — ideal for relaxing between study sessions.\n\nCommunal facilities\n\nCommunal kitchen and cosy living room with television\n\nGarden accessible to all residents\n\nSecure bicycle storage','\n',char(10)),NULL,'2026-02-23 10:07:57','2026-03-23 11:49:50','https://pub-1dc25e3e45174c0e913fc701f51ab106.r2.dev/uploads/b388699b-712a-4a2f-b872-e29eb7b48123-M104-106_gevel.jpg');
