INSERT INTO "audit_logs" ("id","actor_id","action","entity_type","entity_id","changes","created_at") VALUES('7268a7ba65bfaf9e57963f9551aa5f88','e5b2777ae3e9e78f38ba07d59edc2e2f','update','vestigingen','637f58e754b17199ea92ac04c79e74da','{"id":"637f58e754b17199ea92ac04c79e74da","name":"Dreefstraat 104","address":"Dreefstraat 104","city":" Heverlee","postal_code":"3001","description":"Nieuwe, moderne en volledig gemeubelde studentenkamers beschikbaar in verschillende oppervlaktes: 12 m², 14 m², 17 m², 18 m², 21 m² en 35 m². Zo vind je steeds een kamer die perfect aansluit bij jouw wensen en budget.\n\nElke kamer biedt hedendaags comfort in een verzorgde en aangename studentenresidentie in Heverlee.\n\nDaarnaast is er een ruime gemeenschappelijke keuken en gezellige living met televisie voorzien, ideaal om samen te koken, studeren of ontspannen met medestudenten.","description_en":null,"archived_at":null,"created_at":"2026-02-23 10:05:34","updated_at":"2026-03-20 11:57:52","image_url":null}','2026-03-20 11:57:52');
