INSERT INTO "audit_logs" ("id","actor_id","action","entity_type","entity_id","changes","created_at") VALUES('f03e554a5c5b9aa30070235a0de3fcee','e5b2777ae3e9e78f38ba07d59edc2e2f','create','media_assets','d52bb428314c9a7ff46caef3d5dfafd0','{"id":"d52bb428314c9a7ff46caef3d5dfafd0","r2_key":"uploads/b388699b-712a-4a2f-b872-e29eb7b48123-M104-106_gevel.jpg","public_url":"https://pub-1dc25e3e45174c0e913fc701f51ab106.r2.dev/uploads/b388699b-712a-4a2f-b872-e29eb7b48123-M104-106_gevel.jpg","file_name":"M104-106 gevel.jpg","mime_type":"image/jpeg","size_bytes":1005238,"width":null,"height":null,"created_by":"e5b2777ae3e9e78f38ba07d59edc2e2f","created_at":"2026-03-20 11:59:29"}','2026-03-20 11:59:29');
INSERT INTO "audit_logs" ("id","actor_id","action","entity_type","entity_id","changes","created_at") VALUES('a230b347f15402579dee125280c53be8','e5b2777ae3e9e78f38ba07d59edc2e2f','update','vestigingen','04cb31a0552a92bec75648fe4f2a2e32','{"id":"04cb31a0552a92bec75648fe4f2a2e32","name":"J.P. Minckelersstraat 104 – 106","address":"J.P. Minckelersstraat 104 – 106","city":"Leuven","postal_code":"3000","description":"Dit gebouw biedt een ruime keuze aan moderne, gemeubelde studentenkamers in Leuven, geschikt voor uiteenlopende woonwensen.\n\nEr zijn nieuwe en ruime duplexkamers met privé-sanitair, beschikbaar in oppervlaktes van 14 m², 16 m², 17 m², 20 m², 21 m², 25 m² en 30 m². Deze kamers combineren comfort en privacy met toegang tot een gemeenschappelijke keuken en gezellige living met televisie.\n\nDaarnaast zijn er dubbele kamers beschikbaar, eventueel geschikt voor twee personen. Deze kamers zijn volledig van elkaar gescheiden en beschikken over eigen sanitair, wat zorgt voor extra privacy en gebruiksgemak.\n\nHet gebouw biedt ook verschillende ruime kamers en studio’s van 21 m² tot 40 m². Bewoners genieten hier van een gemeenschappelijke tuin en een aangename living met televisie, ideaal om te ontspannen of samen te komen met medestudenten.\n\nVoor alle huurders is een veilige fietsenstalling voorzien.","description_en":null,"archived_at":null,"created_at":"2026-02-23 10:07:57","updated_at":"2026-03-20 11:59:31","image_url":null}','2026-03-20 11:59:31');
INSERT INTO "audit_logs" ("id","actor_id","action","entity_type","entity_id","changes","created_at") VALUES('48e393e5960376e21c9976170c51267f','e5b2777ae3e9e78f38ba07d59edc2e2f','create','media_assets','476691d99a921289c6109971e037726d','{"id":"476691d99a921289c6109971e037726d","r2_key":"uploads/4b22aec7-684f-49b9-b986-02b63a557bcf-J.P._Minckelersstraat_79.png","public_url":"https://pub-1dc25e3e45174c0e913fc701f51ab106.r2.dev/uploads/4b22aec7-684f-49b9-b986-02b63a557bcf-J.P._Minckelersstraat_79.png","file_name":"J.P. Minckelersstraat 79.png","mime_type":"image/png","size_bytes":531042,"width":null,"height":null,"created_by":"e5b2777ae3e9e78f38ba07d59edc2e2f","created_at":"2026-03-20 12:01:51"}','2026-03-20 12:01:51');
INSERT INTO "audit_logs" ("id","actor_id","action","entity_type","entity_id","changes","created_at") VALUES('5fb519b078c27e10dd8c51b93a694ea8','e5b2777ae3e9e78f38ba07d59edc2e2f','update','vestigingen','d51d0e166e3387f845dd7ae64b1490c5','{"id":"d51d0e166e3387f845dd7ae64b1490c5","name":"J.P. Minckelersstraat 79","address":"J.P. Minckelersstraat 79","city":"Leuven","postal_code":"3000","description":"Dit gebouw biedt verschillende types studentenkamers in Leuven, afgestemd op diverse woonwensen en budgetten. Je kan kiezen voor een studentenkamer met gedeeld sanitair of voor een studio met privébadkamer voor extra comfort en privacy.\n\nDe residentie is ideaal gelegen vlak bij het centrum van Leuven, op wandelafstand van universiteit, winkels en openbaar vervoer. Tegelijk geniet je hier van een rustige woonomgeving, weg van de drukte van het stadscentrum.\n\nEen perfecte combinatie van centrale ligging en aangenaam wooncomfort voor studenten die een kot willen huren in Leuven.","description_en":null,"archived_at":null,"created_at":"2026-02-23 10:00:25","updated_at":"2026-03-20 12:01:51","image_url":null}','2026-03-20 12:01:52');
