INSERT INTO "audit_logs" ("id","actor_id","action","entity_type","entity_id","changes","created_at") VALUES('c61da2f3b1a019448898ed9adf5e9046','e5b2777ae3e9e78f38ba07d59edc2e2f','create','media_assets','33c4555207f212559074a3a214f860d7','{"id":"33c4555207f212559074a3a214f860d7","r2_key":"uploads/3f48eef3-34e8-4256-9b35-29e2fd33aa77-Naamsestraat_29A.png","public_url":"https://pub-1dc25e3e45174c0e913fc701f51ab106.r2.dev/uploads/3f48eef3-34e8-4256-9b35-29e2fd33aa77-Naamsestraat_29A.png","file_name":"Naamsestraat 29A.png","mime_type":"image/png","size_bytes":17620,"width":null,"height":null,"created_by":"e5b2777ae3e9e78f38ba07d59edc2e2f","created_at":"2026-03-20 12:04:12"}','2026-03-20 12:04:12');
INSERT INTO "audit_logs" ("id","actor_id","action","entity_type","entity_id","changes","created_at") VALUES('b0d0ca030ebb01cbb2b76b19b38f762f','e5b2777ae3e9e78f38ba07d59edc2e2f','update','vestigingen','ce3bd461f11895258095c5494c23b588','{"id":"ce3bd461f11895258095c5494c23b588","name":"Naamsestraat 29A","address":"Naamsestraat 29A","city":"Leuven","postal_code":"3000","description":"Dit gebouw biedt unieke studentenkamers in het hart van Leuven. Je woont hier op een toplocatie, op wandelafstand van de universiteit, winkels en het bruisende stadsleven.\n\nHet gebouw beschikt over een gezellige centrale buitenruimte met vijf aparte ingangen die elk toegang geven tot verschillende kamers. Daarnaast is er een recent vernieuwde gemeenschappelijke keuken met televisie, ideaal om samen te koken en te ontspannen.\n\nEr is bovendien een veilige en afgesloten fietsenstalling voorzien.\n\nComfort in elke kamer\n\nAlle kamers zijn uitgerust met:\n\nDubbele beglazing\n\nKotnet (internetverbinding)\n\nParlofoon\n\nAansluitmogelijkheid voor kabeltelevisie\n\nWarm en koud water\n\nDe douches en toiletten zijn gemeenschappelijk en worden netjes onderhouden.","description_en":null,"archived_at":null,"created_at":"2026-02-23 09:55:31","updated_at":"2026-03-20 12:04:13","image_url":null}','2026-03-20 12:04:13');
